contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logger, bool status) public payable {
        // Drive the owner-only entry point. The test contract deployed c,
        // so it is the owner and this call must succeed.
        c.setApprovedLogger(logger, status);

        // Read the publicly observable status for the same key.
        bool observed = c.approvedToLog(logger);

        // General rule: the getter mirrors the stored status for every key/status pair.
        assert(observed == status);
    }

    receive() external payable {}
}

