contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _logger, bool _status) public payable {
        bool reverted;
        try c.setApprovedLogger(_logger, _status) { reverted = false; } catch { reverted = true; }
        bool logged = c.approvedToLog(_logger);
        assert(!reverted && logged == _status);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _logger, bool _status) public payable {
        bool revertedFirst;
        bool resultFirst;
        try c.setApprovedLogger(_logger, _status) { revertedFirst = false; resultFirst = true; } catch { revertedFirst = true; resultFirst = false; }
        bool recordedFirst = c.approvedToLog(_logger);
        bool revertedSecond;
        bool resultSecond;
        try c.setApprovedLogger(_logger, !_status) { revertedSecond = false; resultSecond = true; } catch { revertedSecond = true; resultSecond = false; }
        bool recordedSecond = c.approvedToLog(_logger);
        bool current = c.approvedToLog(_logger);
        assert(!revertedFirst && resultFirst && !revertedSecond && resultSecond && recordedFirst == _status && recordedSecond == !_status && current == !_status);
    }
    receive() external payable {}
    fallback() external payable {}
}
